mapper.select:
/* BmsAirDOMapper.selectBmsAirDOList : 항공DO조회 */
SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT , SUM(AA.SIMPLE_CNT) OVER() AS TOTAL_SIMPLE_CNT , SUM(AA.GENERAL_CNT) OVER() AS TOTAL_GENERAL_CNT FROM ( SELECT tbd.DELIVERY_NO , tbi.OD_JOB_NO , CASE WHEN (SELECT TOP 1 tcfs.REFERENCE_NO_ID FROM TB_COM_FILE_SHARE tcfs WHERE tcfs.FUNC_JOB_NO = tbi.OD_JOB_NO ) IS NULL THEN 'N' ELSE 'Y' END AS FILE_SHARE , #{srchCancelYnName} AS lastPodStatus
, '조회' AS blStatus
, tbi.AR_DATE , tbd.RECV_DATE , tbd.RECV_TIME , tbd.CANCEL_YN , tbd.CANCEL_DATE , tbd.CANCEL_TIME , tbd.BL_NO , tbd.MBL_NO , tbi.CARGO_REFERENCE_NO , tbd.CUSTOMER_NAME , tbd.FWD_CODE , tbd.FWD_NAME , tbd.FWD_TEL , tbd.FWD_ATTN_NAME , tbi.CUSTOMER_CODE AS CUSTOMER_CODE_IN , tbi.CUSTOMER_NAME AS CUSTOMER_NAME_IN , tbd.NOTIFY_NAME , tbi.COMMODITY_ITEM_LOC , ISNULL(tbd.WT, 0) AS WT , tbi.CD_TYPE , IIF(tbi.CD_TYPE = 'Y', 1, 0) AS SIMPLE_CNT , IIF(tbi.CD_TYPE = 'N', 1, 0) AS GENERAL_CNT , tbd.LC_YN , tbd.LC_NO , tbd.LC_BANK , tbd.HSN , tbd.REGISTER_USER_ID , (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = tbd.REGISTER_USER_ID) AS REGISTER_USER_NAME , tbd.REGISTER_DATE_TIME FROM TB_BMS_DELIVERY tbd LEFT JOIN TB_BMS_IN tbi WITH (NOLOCK) ON tbd.BL_NO = tbi.BL_NO WHERE 1=1
AND 1 = 0
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(CHAR(10), #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(CHAR(10), #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} >= #{srchStartDate} AND ${srchDateGbn} <= #{srchEndDate}
AND tbd.CANCEL_YN = #{srchCancelYn}
AND tbi.CUSTOMER_CODE = #{srchCustomerCode}
AND tbi.CUSTOMER_NAME LIKE CONCAT('%', #{srchCustomerName}, '%')
AND tbd.FWD_CODE = #{srchFwdCode}
AND tbd.FWD_NAME LIKE CONCAT('%', #{srchFwdName}, '%')
AND tbi.COMMODITY_ITEM_LOC LIKE CONCAT('%', #{srchCommodityItemLocName}, '%')
) AA
